insert into public.site_content_blocks(page_key,block_key,label,default_text) values
('information/patch-165921.html','text-intro','Introduction','Checked 21 October 2026 against patch 165921. These are companion-site findings from recovered configuration data, separate from official patch notes.'),
('information/patch-165921.html','text-status-title','Heading · What has been checked','What has been checked'),
('information/patch-165921.html','note-status-evidence','Info box · Useful patch data; live identity unverified. Patch 165921 contains the additions below. Its exa','Useful patch data; live identity unverified. Patch 165921 contains the additions below. Its exact relationship to the live server payload has not been established. Unchanged website datasets are not automatically verified for this patch.'),
('information/patch-165921.html','text-status-scope','Text · The stats calculator and My Tatari now support recorded account levels 1–3,600. The Horde / Gol','The stats calculator and My Tatari now support recorded account levels 1–3,600. The Horde / Goldrush calculator remains a fixed level-500 comparison. Existing values through level 2,400 match the previous export exactly.'),
('information/patch-165921.html','text-tatari-title','Heading · Bonobean and account levels','Bonobean and account levels'),
('information/patch-165921.html','text-tatari-bonobean','Text · Bonobean is linked to UnitID 68. Its Horde configuration includes two passive skills (6891 and ','Bonobean is linked to UnitID 68. Its Horde configuration includes two passive skills (6891 and 6892) and one active skill (6893). This confirms the records exist; detailed skill behavior and complete artwork integration are still under review.'),
('information/patch-165921.html','text-horde-title','Heading · Horde Season 3 configuration','Horde Season 3 configuration'),
('information/patch-165921.html','text-horde-difficulties','Text · The S3 configuration maps to parameter set 103 and lists Difficulties 1–6. Difficulty 6 uses De','The S3 configuration maps to parameter set 103 and lists Difficulties 1–6. Difficulty 6 uses DefenseID 10306. The older S3 configuration listed only Difficulties 1–4.'),
('information/patch-165921.html','note-horde-seasons','Disclaimer · The detailed wave, chip and economy tables currently shown in the Horde guide remain Season 2 r','The detailed wave, chip and economy tables currently shown in the Horde guide remain Season 2 reference data. They have not been relabelled as Season 3. Specific chip numbers and Horde skill balance changes are not verified by these findings.'),
('information/patch-165921.html','text-collectibles-title','Heading · Collectible additions','Collectible additions'),
('information/patch-165921.html','text-collectibles-accessories','Text · Original and color accessory variants are present for Zapup, Sparkit, Pandaroo, Cheerling, Lull','Original and color accessory variants are present for Zapup, Sparkit, Pandaroo, Cheerling, Lullely, Funglet, Taptail, Budboo, Cavyzap, Ringtail and Popa.'),
('information/patch-165921.html','text-collectibles-limits','Text · The records confirm additions, not their availability on a particular account or release date. ','The records confirm additions, not their availability on a particular account or release date. Cosmetic records are separate from saved Glitter ownership.'),
('information/patch-165921.html','text-events-title','Heading · Halloween and battle setup','Halloween and battle setup'),
('information/patch-165921.html','text-events-halloween','Text · Trick-or-Treat reward configuration and the strings “Trick-or-Treat Time!” and “Halloween Fun!”','Trick-or-Treat reward configuration and the strings “Trick-or-Treat Time!” and “Halloween Fun!” are present. The event dates and exact replacement schedule are not established, so the site calendar has not been rescheduled from this evidence alone.'),
('information/patch-165921.html','text-events-battles','Text · The patch contains 429 new and 404 changed StageBattle files. These counts describe files, not ','The patch contains 429 new and 404 changed StageBattle files. These counts describe files, not player-facing changes. Their chapter mapping is still under review; formation recommendations have not been recalibrated from the counts alone.'),
('information/patch-165921.html','text-pending-title','Heading · Still unverified','Still unverified'),
('information/patch-165921.html','list-pending-unknowns-1','List item · Goldrush weekly giftbox limit','Goldrush weekly giftbox limit'),
('information/patch-165921.html','list-pending-unknowns-2','List item · Horde chip balance values','Horde chip balance values'),
('information/patch-165921.html','list-pending-unknowns-3','List item · Specific Horde skill balance changes','Specific Horde skill balance changes'),
('information/patch-165921.html','list-pending-unknowns-4','List item · Boss Challenge merge changes','Boss Challenge merge changes'),
('information/patch-165921.html','list-pending-unknowns-5','List item · Halloween event dates and replacement timing','Halloween event dates and replacement timing'),
('information/patch-165921.html','list-pending-unknowns-6','List item · Exact match to the live server payload','Exact match to the live server payload'),
('information/patch-165921.html','text-pending-source','Text · Evidence: recovered Unit, Pet, ProfilePicture, UnitLevel, UnitAttrLevel, LuckyDefenseSeasonConf','Evidence: recovered Unit, Pet, ProfilePicture, UnitLevel, UnitAttrLevel, LuckyDefenseSeasonConfig, LuckyDefenseConfig and PetCollectible records, plus decoded English language data. Raw game code and packages are kept offline.')
